public class StringCompareDemo {
    public static void main(String[] args) {

        String s1 = "hello";             // literal → goes to pool
        String s2 = "hello";             // literal → same pooled object
        String s3 = new String("hello");  // always new heap object

        System.out.println(s1 == s2);      // true — accident of the pool
        System.out.println(s1 == s3);      // false — different objects
        System.out.println(s1.equals(s2)); // true
        System.out.println(s1.equals(s3)); // true — content matches

        // The real-world case where == silently breaks:
        String fromUser = new String("hello"); // simulates scanner/API input
        if (fromUser == "hello") {             // FALSE — always, even if text matches
            System.out.println("Won't print");
        }
        if (fromUser.equals("hello")) {        // TRUE — correct
            System.out.println("Match!");
        }

        // Null-safe pattern — put the literal first to avoid NullPointerException
        String maybeNull = null;
        // maybeNull.equals("hello")           // NullPointerException
        System.out.println("hello".equals(maybeNull)); // false — safe
        System.out.println(java.util.Objects.equals(maybeNull, "hello")); // false — null-safe
    }
}
