import java.util.Arrays;

public class CompareToDemo {
    public static void main(String[] args) {

        System.out.println("apple".compareTo("apple"));  // 0  — equal
        System.out.println("apple".compareTo("banana")); // negative — apple comes before banana
        System.out.println("banana".compareTo("apple")); // positive — banana comes after apple

        // Sorting strings alphabetically — compareTo() is used internally
        String[] fruits = {"Mango", "Apple", "Banana", "Cherry"};
        Arrays.sort(fruits);
        System.out.println(Arrays.toString(fruits)); // [Apple, Banana, Cherry, Mango]

        // Case-insensitive ordering
        System.out.println("Apple".compareTo("apple"));           // negative — 'A'(65) < 'a'(97)
        System.out.println("Apple".compareToIgnoreCase("apple"));  // 0 — case ignored

        // Manual comparison — check sign only
        String s1 = "orange";
        String s2 = "grape";
        if (s1.compareTo(s2) > 0) {
            System.out.println(s2 + " comes before " + s1); // grape comes before orange
        }
    }
}
