public class StringSearchDemo {
    public static void main(String[] args) {
        String url = "https://www.example.com/products";

        // contains() — is the substring anywhere in the string?
        System.out.println(url.contains("example")); // true
        System.out.println(url.contains("EXAMPLE")); // false — case-sensitive!

        // startsWith() — does it begin with this?
        System.out.println(url.startsWith("https")); // true
        System.out.println(url.startsWith("http://")); // false

        // endsWith() — does it end with this?
        System.out.println(url.endsWith("/products")); // true
        System.out.println(url.endsWith(".html"));     // false

        // indexOf() — WHERE is the match? Returns -1 if not found
        System.out.println(url.indexOf("example"));  // 12 — start index
        System.out.println(url.indexOf("EXAMPLE"));  // -1 — case-sensitive, not found

        // Case-insensitive search — normalise both sides
        String search = "EXAMPLE";
        System.out.println(url.toLowerCase().contains(search.toLowerCase())); // true
    }
}
