import java.util.Locale;

public class CaseInsensitiveDemo {
    public static void main(String[] args) {

        // equalsIgnoreCase — built-in, no transformation needed
        System.out.println("Hello".equalsIgnoreCase("hello"));     // true
        System.out.println("JAVA".equalsIgnoreCase("java"));       // true
        System.out.println("Java".equalsIgnoreCase("javascript")); // false

        // compareToIgnoreCase — ordering, case ignored
        System.out.println("Apple".compareToIgnoreCase("apple"));  // 0 — equal
        System.out.println("Apple".compareToIgnoreCase("Banana")); // negative — apple < banana

        // contains/startsWith/endsWith — no built-in, normalise both sides
        String url = "https://www.Example.com";
        String search = "EXAMPLE";

        // WRONG — only one side normalised
        System.out.println(url.toLowerCase().contains(search));               // false!

        // CORRECT — both sides normalised
        System.out.println(url.toLowerCase().contains(search.toLowerCase())); // true

        // Production-safe with Locale.ROOT
        System.out.println(
            url.toLowerCase(Locale.ROOT).contains(search.toLowerCase(Locale.ROOT))
        ); // true — avoids Turkish locale issue
    }
}
